CREATE OR ALTER VIEW DBO.VWK_IMOVH_AGRUPADO
AS
	SELECT IMOVH.CNSMOV, IMOVH.IDARTICULO, IART.DESCRIPCION, IMOVH.NOLOTEPEDIDO,IMOVH.FECHAVENCE
		,CAST(SUM(IMOVH.CANTIDAD) AS DECIMAL(14,2)) CANTIDAD, CAST(SUM(IMOVH.CANTPEDIDA) AS DECIMAL(14,2)) AS CANTPEDIDA	
		,IMOVH.PCOSTO AS COSTO--CAST(ISNULL((SELECT TOP 1 T.PCOSTO FROM IMOVH T WHERE T.CNSMOV=IMOVH.CNSMOV AND T.IDARTICULO=IMOVH.IDARTICULO AND T.NOLOTE=IMOVH.NOLOTE),0) AS DECIMAL(14,2)) COSTO
		,CAST(ISNULL((SELECT TOP 1 T.PVENTA FROM IMOVH T WHERE T.CNSMOV=IMOVH.CNSMOV AND T.IDARTICULO=IMOVH.IDARTICULO AND T.NOLOTEPEDIDO=IMOVH.NOLOTEPEDIDO),0) AS DECIMAL(14,2)) PRECIO
		/* El IVA sale del mismo grupo (lote, vencimiento, estado y costo).
		   Una suma solo por artículo o por lote se repetía en cada fila y la CxP
		   guardaba el total de la factura en cada línea. */
		,SUM(ISNULL(IMOVH.VLRIVA,0)) AS IVA
		/* bugfix/MEDICAL782 -- 2026-09-08 -- PIVA para saber si PCOSTO ya trae IVA o el IVA va aparte. */
		,ISNULL((SELECT TOP 1 T.PIVA FROM IMOVH T WHERE T.CNSMOV=IMOVH.CNSMOV AND T.IDARTICULO=IMOVH.IDARTICULO AND T.NOLOTEPEDIDO=IMOVH.NOLOTEPEDIDO),0) PIVA
		,ISNULL((SELECT TOP 1 T.VLRDTO FROM IMOVH T WHERE T.CNSMOV=IMOVH.CNSMOV AND T.IDARTICULO=IMOVH.IDARTICULO AND T.NOLOTEPEDIDO=IMOVH.NOLOTEPEDIDO),0) DESCUENTO
		,CAST(ISNULL((SELECT SUM(ISNULL(T.PCOSTO,0)) FROM IMOVH T WHERE T.CNSMOV=IMOVH.CNSMOV AND T.IDARTICULO=IMOVH.IDARTICULO AND T.NOLOTEPEDIDO=IMOVH.NOLOTEPEDIDO),0) AS DECIMAL(14,2)) TOTALCOSTO
		,CAST(ISNULL((SELECT SUM(ISNULL(T.PCOSTO,0)) FROM IMOVH T WHERE T.CNSMOV=IMOVH.CNSMOV AND T.IDARTICULO=IMOVH.IDARTICULO AND T.NOLOTEPEDIDO=IMOVH.NOLOTEPEDIDO),0) AS DECIMAL(14,2)) TOTALPRECIO
		/* bugfix/MEDICAL782 -- 2026-09-08 -- No convertir NULL de impuesto/clase a 0 (rompe FIMPD). */
		,(SELECT TOP 1 T.IDIMPUESTO FROM IMOVH T WHERE T.CNSMOV=IMOVH.CNSMOV AND T.IDARTICULO=IMOVH.IDARTICULO AND T.NOLOTEPEDIDO=IMOVH.NOLOTEPEDIDO) IDIMPUESTO
		,(SELECT TOP 1 T.IDCLASE FROM IMOVH T WHERE T.CNSMOV=IMOVH.CNSMOV AND T.IDARTICULO=IMOVH.IDARTICULO AND T.NOLOTEPEDIDO=IMOVH.NOLOTEPEDIDO) IDCLASE
		,ISNULL((SELECT TOP 1 T.VLRIMPCONSUMO FROM IMOVH T WHERE T.CNSMOV=IMOVH.CNSMOV AND T.IDARTICULO=IMOVH.IDARTICULO AND T.NOLOTEPEDIDO=IMOVH.NOLOTEPEDIDO),0) VLRIMPCONSUMO
		,IMOVH.ESTADO
	FROM IMOVH	INNER JOIN IMOV ON IMOV.CNSMOV=IMOVH.CNSMOV
			INNER JOIN IART ON IART.IDARTICULO=IMOVH.IDARTICULO	
	GROUP BY IMOVH.CNSMOV, IMOVH.IDARTICULO, IART.DESCRIPCION, IMOVH.NOLOTEPEDIDO, IMOVH.FECHAVENCE,IMOVH.ESTADO,IMOVH.PCOSTO
